<div class="us-form-grid"><label class="us-field">Role Name<input name="name" value="{{old('name',$editRole?->name)}}" required></label><label class="us-field">Display Label<input name="label" value="{{old('label',$editRole?->label)}}" required></label><label class="us-field">Type<select name="type"><option value="system" @selected(old('type',$editRole?->type)==='system')>System</option><option value="custom" @selected(old('type',$editRole?->type??'custom')==='custom')>Custom</option><option value="api" @selected(old('type',$editRole?->type)==='api')>API</option></select></label><label class="us-field">Level<input type="number" min="1" max="9" name="level" value="{{old('level',$editRole?->level??5)}}" required></label><label class="us-field span-2">Description<textarea name="description" rows="2">{{old('description',$editRole?->description)}}</textarea></label></div><fieldset class="us-fieldset"><legend>Permissions</legend><div class="us-permission-checks">@foreach($permissions->groupBy(fn($p)=>$p->module?:$p->group) as $module=>$modulePermissions)<section><b>{{$module}}</b>@foreach($modulePermissions as $permission)<label><input type="checkbox" name="permission_ids[]" value="{{$permission->id}}" @checked(in_array($permission->id,old('permission_ids',$editRole?->permissions?->pluck('id')->all()??[])))>{{Str::headline($permission->action)}}</label>@endforeach</section>@endforeach</div></fieldset>
